# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require "rake"
require "webmock/rspec"

RSpec.describe "timekeeping:alerts untrusted event history rows" do
  include ActiveSupport::Testing::TimeHelpers

  it "alerts on a stored reconciliation event whose payload names no company under company_id=all without crashing" do
    now = Time.utc(2026, 3, 3, 12, 7)
    TimekeepingOwnership.ensure_initial!
    # Event history rows are free-form JSON captured by name pattern, so a row
    # with no company_id must still raise the alert rather than vanish or crash the run.
    RailsEventViewer::Entry.create!(
      name: "Timekeeping::ReconciliationDifferenceFound",
      occurred_at: now - 1.minute,
      payload: { "data" => { "check" => "entries", "listed" => false } }
    )

    base_url = "http://timekeeping.untrusted-rows.test"
    service_token = "service-#{SecureRandom.hex(16)}"
    stub_request(:get, "#{base_url}/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{service_token}" })
      .to_return(status: 200, headers: { "Content-Type" => "application/json" }, body: {
        "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
        "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
        "companies" => [], "outbox_lag" => []
      }.to_json)

    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    task = Rake::Task["timekeeping:alerts"]
    task.reenable
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = base_url
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = service_token
    output = StringIO.new
    original_stdout = $stdout
    exit_status = 0
    begin
      $stdout = output
      travel_to(now) { task.invoke }
    rescue SystemExit => e
      exit_status = e.status
    ensure
      $stdout = original_stdout
      %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
    end

    alert_lines = output.string.lines.select do |line|
      line.include?("reconciliation_difference") && !line.match?(/unavailable/i)
    end
    expect(alert_lines.size).to eq(1)
    expect(alert_lines.first).to include("company_id=all")
    expect(exit_status).to eq(0)
  end
end

RSpec.describe "timekeeping:alerts financial snapshot change output" do
  include ActiveSupport::Testing::TimeHelpers

  it "reports a financial snapshot change by company without printing money values or the service token" do
    now = Time.utc(2026, 3, 3, 12, 7)
    TimekeepingOwnership.ensure_initial!
    company = create(:company)
    difference = Timekeeping::FinancialSnapshot::Difference.new(
      company_id: company.id, kind: :invoice, record_id: 4242, field: :amount,
      old_value: BigDecimal("731.19"), new_value: BigDecimal("917.53")
    )
    travel_to(now - 1.minute) { Timekeeping::FinancialSnapshot.report([difference]) }

    base_url = "http://timekeeping.snapshot-output.test"
    service_token = "service-#{SecureRandom.hex(16)}"
    stub_request(:get, "#{base_url}/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{service_token}" })
      .to_return(status: 200, headers: { "Content-Type" => "application/json" }, body: {
        "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
        "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
        "companies" => [], "outbox_lag" => []
      }.to_json)

    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    task = Rake::Task["timekeeping:alerts"]
    task.reenable
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = base_url
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = service_token
    output = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = output
      travel_to(now) { task.invoke }
    rescue SystemExit
      nil
    ensure
      $stdout = original_stdout
      %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
    end

    alert_lines = output.string.lines.select do |line|
      line.include?("financial_snapshot_change") && !line.match?(/unavailable/i)
    end
    expect(alert_lines.size).to eq(1)
    expect(alert_lines.first).to include("company_id=#{company.id}")
    # Event history is readable across every workspace, so the alert names the
    # company but never the invoice money values, and never the service credential.
    expect(output.string).not_to include("731.19")
    expect(output.string).not_to include("917.53")
    expect(output.string).not_to include(service_token)
  end
end
